package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import org.json.*;
public final class LitSceneGpuInstrumentation extends SceneGpuInstrumentation {
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{
  NativeSceneSnapshot scene=new NativeSceneSnapshot(Files.readAllBytes(new File(getTargetContext().getFilesDir(),"lit-scene-whole.nab").toPath()));NativeSceneDrawPlan plan=new NativeSceneDrawPlan(scene.geometry(0));int lit=0;for(int i=0;i<plan.count();i++)if(plan.draw(i).lighting!=null)lit++;ok(lit==7,"Seven explicit synthetic lit walls required");
  startGl();live=true;String small=render(scene,240,160,240,160,"lit-scene-240.png",false),large=render(scene,3840,2160,3240,2160,"lit-scene-4k.png",false);ok(litZeroChecks>0&&litSkipChecks>0,"Lit zero/skip paths missing");endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Lit context changed pixels");
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_LIT_SCENE_GLES");report.put("source_commands",plan.count());report.put("lit_walls",lit);report.put("renderer",renderer);report.put("api",Build.VERSION.SDK_INT);report.put("source_pixel_checks",checks);report.put("lit_zero_write_evaluations",litZeroChecks);report.put("lit_skip_evaluations",litSkipChecks);report.put("lit_level_mask",litLevelsMask);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("synthetic_materials",true);report.put("captured_geometry",true);report.put("context_recreated",true);report.put("full_scene",false);report.put("real_time_pacing",false);try(FileOutputStream out=getTargetContext().openFileOutput("lit-scene-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
